// ExactReview's data module. Two modes, picked in Settings and persisted on
// the device (never in the repo):
//
//   fixture — deterministic data generated by fixturelib.ts, byte-identical
//             to the Rust app's benchmark harness (same seed, same generator).
//             Comments and approvals are recorded in memory and echoed back.
//   live    — the real GitHub REST/GraphQL API with the saved token.
//
// The diff pipeline parses unified patches once per pull, classifies files
// (generated/large start collapsed — the same rules the Rust app uses), and
// ships rows inline only under explicit caps; anything bigger is served per
// file through loadLazyRows. Nothing about the caps is hidden: the file row
// and the diff stats bar both report truncation and drops.

import type { Answer, Result, Sources } from './app.contract.d.ts';
import { fixtureDiff, generateBodyMarkdown, generatePulls, type FixturePull } from './fixturelib.ts';

export const grants = 'net.fetch https://api.github.com\nfs.read app:/data/settings.json\nfs.write app:/data/settings.json';

type PullRow = Result<'loadPulls'>['pulls'][number];
type DiffRow = Result<'loadDiff'>['files'][number]['rows'][number];
type DiffFile = Result<'loadDiff'>['files'][number];
type Reply = Result<'postComment'>;

// --- settings -------------------------------------------------------------

interface Settings { mode: 'fixture' | 'live'; token: string }

const SETTINGS_FILE = 'app:/data/settings.json';
type Storage = Parameters<Answer>[3];

async function readSettings(storage: Storage): Promise<Settings> {
  try {
    const bytes = await storage.fs.readFile(SETTINGS_FILE);
    const parsed = JSON.parse(new TextDecoder().decode(bytes)) as Partial<Settings>;
    return { mode: parsed.mode === 'live' ? 'live' : 'fixture', token: typeof parsed.token === 'string' ? parsed.token : '' };
  } catch {
    return { mode: 'fixture', token: '' };
  }
}

async function writeSettings(storage: Storage, settings: Settings): Promise<void> {
  await storage.fs.atomicWriteFile(SETTINGS_FILE, new TextEncoder().encode(JSON.stringify(settings)));
}

// --- fixtures -------------------------------------------------------------

const FIXTURE_COUNT = 400;
let fixturePulls: FixturePull[] | null = null;

function pullsFixture(): FixturePull[] {
  fixturePulls ??= generatePulls(FIXTURE_COUNT);
  return fixturePulls!;
}

function relativeLabel(iso: string, nowMs: number): string {
  const delta = Math.max(0, nowMs - Date.parse(iso));
  const minutes = Math.floor(delta / 60_000);
  if (minutes < 60) return `${minutes}m`;
  const hours = Math.floor(minutes / 60);
  if (hours < 48) return `${hours}h`;
  return `${Math.floor(hours / 24)}d`;
}

function toRow(pull: FixturePull, nowMs: number): PullRow {
  return {
    id: pull.id,
    number: pull.number,
    title: pull.title,
    repo: pull.repository.nameWithOwner,
    author: pull.author?.login ?? '',
    additions: pull.additions,
    deletions: pull.deletions,
    changedFiles: pull.changedFiles,
    checkState: pull.commits.nodes[0]?.commit.statusCheckRollup?.state ?? '',
    review: pull.reviewDecision ?? '',
    draft: pull.isDraft,
    updatedLabel: relativeLabel(pull.updatedAt, nowMs),
  };
}

// The fixture clock is pinned so benchmarks are deterministic; the data
// module is refused wall-clock access, so "now" for fixture labels is the
// fixture's own noon.
const FIXTURE_NOW_MS = Date.parse('2026-09-26T12:00:00Z');

// --- unified diff parsing ---------------------------------------------------

const LARGE_FILE_LINES = 1500;
const GENERATED_FILE = /(^|\/)(bun\.lock|package-lock\.json|yarn\.lock|pnpm-lock\.yaml|Cargo\.lock)$|\.snap$|\.min\.(js|css)$/;
// Honest caps, reported in the UI and in BENCH.md:
const MAX_FILES = 3000; // GitHub's own files API serves at most 3000
const INLINE_FILE_ROWS = 1500; // at/under this a file's rows ship with the summary
const INLINE_TOTAL_ROWS = 12000; // past this, later small files turn lazy too
const MAX_FILE_ROWS = 20000; // one file never contributes more; the rest is truncated

interface ParsedLine { kind: 'add' | 'del' | 'context' | 'hunk' | 'meta'; text: string; oldNo: number; newNo: number }
interface ParsedFile {
  name: string;
  additions: number;
  deletions: number;
  lines: ParsedLine[];
}

function parsePatch(patch: string): ParsedFile[] {
  const files: ParsedFile[] = [];
  let file: ParsedFile | null = null;
  let oldNo = 0;
  let newNo = 0;
  for (const raw of patch.split('\n')) {
    if (raw.startsWith('diff --git ')) {
      const names = /^diff --git a\/(.+) b\/(.+)$/.exec(raw);
      file = { name: names?.[2] ?? raw.slice(11), additions: 0, deletions: 0, lines: [] };
      files.push(file);
      continue;
    }
    if (file == null) continue;
    if (raw.startsWith('rename to ')) {
      file.name = raw.slice(10);
      file.lines.push({ kind: 'meta', text: raw, oldNo: 0, newNo: 0 });
      continue;
    }
    if (raw.startsWith('rename from ') || raw.startsWith('new file mode') || raw.startsWith('deleted file mode') || raw.startsWith('similarity index') || raw.startsWith('index ')) {
      file.lines.push({ kind: 'meta', text: raw, oldNo: 0, newNo: 0 });
      continue;
    }
    if (raw.startsWith('Binary files') || raw.startsWith('GIT binary patch')) {
      file.lines.push({ kind: 'meta', text: raw, oldNo: 0, newNo: 0 });
      continue;
    }
    if (raw.startsWith('--- ') || raw.startsWith('+++ ')) continue; // redundant with the header
    if (raw.startsWith('@@ ')) {
      const hunk = /^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/.exec(raw);
      oldNo = hunk ? Number(hunk[1]) : 0;
      newNo = hunk ? Number(hunk[2]) : 0;
      file.lines.push({ kind: 'hunk', text: raw, oldNo: 0, newNo: 0 });
      continue;
    }
    if (raw.startsWith('\\')) {
      file.lines.push({ kind: 'meta', text: raw, oldNo: 0, newNo: 0 });
      continue;
    }
    const marker = raw[0] ?? ' ';
    if (marker === '+') {
      file.additions += 1;
      file.lines.push({ kind: 'add', text: raw.slice(1), oldNo: 0, newNo });
      newNo += 1;
    } else if (marker === '-') {
      file.deletions += 1;
      file.lines.push({ kind: 'del', text: raw.slice(1), oldNo, newNo: 0 });
      oldNo += 1;
    } else {
      file.lines.push({ kind: 'context', text: raw.slice(1), oldNo, newNo });
      oldNo += 1;
      newNo += 1;
    }
  }
  return files;
}

interface ShapedDiff {
  data: Result<'loadDiff'>;
  /** Rows per file index for lazy serving; absent for inline files. */
  lazyRows: Map<number, DiffRow[]>;
}

function shapeDiff(pullId: string, patch: string): ShapedDiff {
  const parsed = parsePatch(patch);
  const droppedFiles = Math.max(0, parsed.length - MAX_FILES);
  const kept = parsed.slice(0, MAX_FILES);
  const files: DiffFile[] = [];
  const lazyRows = new Map<number, DiffRow[]>();
  let inlineTotal = 0;
  let totalLines = 0;
  for (const [index, pf] of kept.entries()) {
    totalLines += pf.lines.length;
    const generated = GENERATED_FILE.test(pf.name);
    const lineCount = pf.lines.length;
    // Row budget: header row plus content rows, capped per file.
    const truncated = lineCount > MAX_FILE_ROWS;
    const visible = truncated ? pf.lines.slice(0, MAX_FILE_ROWS) : pf.lines;
    const large = lineCount > LARGE_FILE_LINES;
    const overInline = inlineTotal + visible.length + 1 > INLINE_TOTAL_ROWS;
    const lazy = truncated || large || overInline || visible.length + 1 > INLINE_FILE_ROWS;
    inlineTotal += lazy ? 1 : visible.length + 1;

    const contentRows: DiffRow[] = visible.map((line, rowIndex) => ({
      id: `f${index}.${rowIndex + 1}`,
      fileIndex: index,
      kind: line.kind,
      text: line.text,
      aux: '',
      oldNo: line.oldNo,
      newNo: line.newNo,
    }));
    if (truncated) {
      contentRows.push({
        id: `f${index}.truncated`,
        fileIndex: index,
        kind: 'notice',
        text: `… truncated at ${MAX_FILE_ROWS.toLocaleString('en-US')} of ${lineCount.toLocaleString('en-US')} rows — the rest is on GitHub`,
        aux: '',
        oldNo: 0,
        newNo: 0,
      });
    }

    const stat = `+${pf.additions} −${pf.deletions} · ${lineCount.toLocaleString('en-US')} lines`;
    const auxBits: string[] = [stat];
    if (generated) auxBits.push('generated');
    if (lazy) auxBits.push('loads on expand');
    if (truncated) auxBits.push('truncated');
    const header: DiffRow = {
      id: `f${index}`,
      fileIndex: index,
      kind: 'file',
      text: pf.name,
      aux: auxBits.join(' · '),
      oldNo: 0,
      newNo: 0,
    };

    if (lazy) {
      const notice: DiffRow = {
        id: `f${index}.loading`,
        fileIndex: index,
        kind: 'notice',
        text: `Large file — ${lineCount.toLocaleString('en-US')} rows load when expanded.`,
        aux: '',
        oldNo: 0,
        newNo: 0,
      };
      files.push({
        id: `f${index}`,
        index,
        name: pf.name,
        stat,
        rowCount: contentRows.length + 1,
        lineCount,
        startCollapsed: true,
        lazy: true,
        truncated,
        generated,
        rows: [header, notice],
      });
      lazyRows.set(index, contentRows);
    } else {
      files.push({
        id: `f${index}`,
        index,
        name: pf.name,
        stat,
        rowCount: contentRows.length + 1,
        lineCount,
        startCollapsed: generated,
        lazy: false,
        truncated,
        generated,
        rows: [header, ...contentRows],
      });
    }
  }
  return {
    data: {
      pullId,
      fileCount: files.length,
      totalLines,
      droppedFiles,
      files,
    },
    lazyRows,
  };
}

// --- fixture diff cache -------------------------------------------------------

const diffCache = new Map<string, ShapedDiff>();

function fixtureShapedDiff(pullId: string): ShapedDiff {
  const cached = diffCache.get(pullId);
  if (cached != null) return cached;
  const pull = pullsFixture().find((candidate) => candidate.id === pullId);
  const patch = pull == null ? '' : fixtureDiff(pull);
  const shaped = shapeDiff(pullId, patch);
  if (diffCache.size >= 24) diffCache.delete(diffCache.keys().next().value!);
  diffCache.set(pullId, shaped);
  return shaped;
}

// --- live GitHub ------------------------------------------------------------

const API = 'https://api.github.com';

async function gh(token: string, path: string, init?: RequestInit): Promise<Response> {
  const response = await fetch(`${API}${path}`, {
    ...init,
    headers: {
      accept: 'application/vnd.github+json',
      'x-github-api-version': '2022-11-28',
      authorization: `Bearer ${token}`,
      ...(init?.headers ?? {}),
    },
    exactTimeout: 30_000,
  } as RequestInit);
  return response;
}

async function ghJson(token: string, path: string): Promise<unknown> {
  const response = await gh(token, path);
  if (!response.ok) throw new Error(`GitHub answered ${response.status}`);
  return response.json();
}

interface LivePull {
  id: string;
  number: number;
  title: string;
  html_url: string;
  draft: boolean;
  created_at: string;
  updated_at: string;
  user: { login: string } | null;
  repository_url: string;
  pull_request?: { url: string };
}

async function livePulls(token: string): Promise<FixturePull[]> {
  const query = encodeURIComponent('type:pr state:open review-requested:@me');
  const body = (await ghJson(token, `/search/issues?q=${query}&per_page=100&sort=updated`)) as { items?: LivePull[] };
  const items = body.items ?? [];
  return items.map((item) => {
    const repo = item.repository_url.replace(/^https?:\/\/api\.github\.com\/repos\//, '');
    return {
      id: item.id,
      number: item.number,
      title: item.title,
      url: item.html_url,
      isDraft: item.draft,
      createdAt: item.created_at,
      updatedAt: item.updated_at,
      additions: 0,
      deletions: 0,
      changedFiles: 0,
      headRefName: '',
      baseRefName: 'main',
      reviewDecision: null,
      mergeQueueEntry: null,
      author: { login: item.user?.login ?? '', avatarUrl: '' },
      repository: { nameWithOwner: repo },
      commits: { nodes: [{ commit: { statusCheckRollup: null } }] },
    };
  });
}

async function liveDiffText(token: string, repo: string, number: number): Promise<string> {
  const response = await gh(token, `/repos/${repo}/pulls/${number}`, {
    headers: { accept: 'application/vnd.github.v3.diff' },
  });
  if (!response.ok) throw new Error(`GitHub answered ${response.status}`);
  return response.text();
}

// --- sources -------------------------------------------------------------------

const sources: Sources = {
  loadSettings: async (_args, _store, storage) => {
    const settings = await readSettings(storage);
    return { mode: settings.mode, hasToken: settings.token !== '' };
  },

  saveSettings: async ([mode, token], _store, storage) => {
    const current = await readSettings(storage);
    const next: Settings = {
      mode: mode === 'live' ? 'live' : 'fixture',
      token: token === 'forget' ? '' : token === '' ? current.token : token,
    };
    await writeSettings(storage, next);
    return { ok: true, error: '', url: '' };
  },

  loadPulls: async (_args, _store, storage) => {
    const settings = await readSettings(storage);
    if (settings.mode === 'live') {
      if (settings.token === '') {
        return { pulls: [], mode: 'live', note: 'Live mode needs a GitHub token — save one in Settings.' };
      }
      const live = await livePulls(settings.token);
      // The data module has no clock access; live rows label their update day
      // rather than a relative age.
      return {
        pulls: live.map((pull) => ({ ...toRow(pull, FIXTURE_NOW_MS), updatedLabel: pull.updatedAt.slice(0, 10) })),
        mode: 'live',
        note: live.length === 0 ? 'No open pull requests request your review.' : '',
      };
    }
    const pulls = pullsFixture().map((pull) => toRow(pull, FIXTURE_NOW_MS));
    return { pulls, mode: 'fixture', note: '' };
  },

  loadDetail: async ([id], _store, storage) => {
    const settings = await readSettings(storage);
    if (settings.mode === 'live' && settings.token !== '') {
      const found = await livePulls(settings.token).then((ps) => ps.find((p) => p.id === id));
      if (found == null) throw new Error('pull not found in the live queue');
      const repo = found.repository.nameWithOwner;
      const pr = (await ghJson(settings.token, `/repos/${repo}/pulls/${found.number}`)) as {
        title: string; body?: string | null; additions: number; deletions: number; changed_files: number; user: { login: string } | null; head: { ref: string };
      };
      return {
        id, number: found.number, title: pr.title, repo, url: found.url,
        author: pr.user?.login ?? '', branch: pr.head.ref,
        bodyMarkdown: pr.body ?? '', additions: pr.additions, deletions: pr.deletions,
        changedFiles: pr.changed_files, review: '',
      };
    }
    const pull = pullsFixture().find((candidate) => candidate.id === id);
    if (pull == null) throw new Error('no such fixture pull');
    return {
      id: pull.id,
      number: pull.number,
      title: pull.title,
      repo: pull.repository.nameWithOwner,
      url: pull.url,
      author: pull.author.login,
      branch: pull.headRefName,
      bodyMarkdown: generateBodyMarkdown(pull),
      additions: pull.additions,
      deletions: pull.deletions,
      changedFiles: pull.changedFiles,
      review: pull.reviewDecision ?? '',
    };
  },

  loadDiff: async ([id], _store, storage) => {
    const settings = await readSettings(storage);
    if (settings.mode === 'live' && settings.token !== '') {
      const found = await livePulls(settings.token).then((ps) => ps.find((p) => p.id === id));
      if (found == null) throw new Error('pull not found in the live queue');
      const text = await liveDiffText(settings.token, found.repository.nameWithOwner, found.number);
      const shaped = shapeDiff(id, text);
      diffCache.set(id, shaped);
      return shaped.data;
    }
    return fixtureShapedDiff(id).data;
  },

  loadLazyRows: async ([id, keys], _store, storage) => {
    const settings = await readSettings(storage);
    const shaped = settings.mode === 'live' && settings.token !== '' ? diffCache.get(id) ?? fixtureShapedDiff(id) : fixtureShapedDiff(id);
    const wanted = String(keys).split(',').filter((part) => part !== '').map(Number);
    return {
      pullId: id,
      files: wanted.flatMap((index) => {
        const rows = shaped.lazyRows.get(index);
        return rows == null ? [] : [{ fileIndex: index, rows }];
      }),
    };
  },

  postComment: async ([id, body], _store, storage) => {
    const settings = await readSettings(storage);
    if (settings.mode === 'live' && settings.token !== '') {
      const found = await livePulls(settings.token).then((ps) => ps.find((p) => p.id === id));
      if (found == null) return { ok: false, error: 'pull not found', url: '' };
      const response = await gh(settings.token, `/repos/${found.repository.nameWithOwner}/issues/${found.number}/comments`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ body }),
      });
      if (!response.ok) return { ok: false, error: `GitHub answered ${response.status}`, url: '' };
      const created = (await response.json()) as { html_url?: string };
      return { ok: true, error: '', url: created.html_url ?? '' };
    }
    // Fixture mode: record the comment in memory only. Posted fixtures never
    // leave the device.
    fixtureComments.push({ pullId: id, body });
    return { ok: true, error: '', url: `https://github.com/o/web/pull/${id}#issuecomment-fixture` };
  },

  postApproval: async ([id], _store, storage) => {
    const settings = await readSettings(storage);
    if (settings.mode === 'live' && settings.token !== '') {
      const found = await livePulls(settings.token).then((ps) => ps.find((p) => p.id === id));
      if (found == null) return { ok: false, error: 'pull not found', url: '' };
      const response = await gh(settings.token, `/repos/${found.repository.nameWithOwner}/pulls/${found.number}/reviews`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ event: 'APPROVE' }),
      });
      if (!response.ok) return { ok: false, error: `GitHub answered ${response.status}`, url: '' };
      return { ok: true, error: '', url: '' };
    }
    fixtureApprovals.push(id);
    return { ok: true, error: '', url: '' };
  },
};

/** What fixture mode recorded, for tests and benchmark work-checks. */
export const fixtureComments: { pullId: string; body: string }[] = [];
export const fixtureApprovals: string[] = [];

export const answer: Answer = (source, args, store, storage, native) => sources[source](args, store, storage, native);
